def permission_allows(required, granted):
    if type(required) is not str or type(granted) is not tuple:
        raise TypeError('permission_input_invalid')
    if not required.strip():
        raise ValueError('required_blank')
    if any(type(item) is not str for item in granted):
        raise TypeError('granted_item_invalid')
    if any(not item.strip() for item in granted):
        raise ValueError('granted_blank')
    if len(set(granted)) != len(granted):
        raise ValueError('granted_duplicate')
    return required in granted

def lookup_tool_policy(tool, registry):
    if type(tool) is not str or type(registry) is not dict:
        raise TypeError('registry_input_invalid')
    if not tool.strip():
        raise ValueError('tool_blank')
    for name, policy in registry.items():
        if type(name) is not str or type(policy) is not dict:
            raise TypeError('registry_entry_invalid')
        if not name.strip() or set(policy) != {'mode','permission','arguments'}:
            raise ValueError('registry_shape_invalid')
        if policy['mode'] not in {'read','write'}:
            raise ValueError('mode_invalid')
        if type(policy['permission']) is not str or type(policy['arguments']) is not tuple:
            raise TypeError('policy_value_invalid')
        if not policy['permission'].strip():
            raise ValueError('permission_blank')
        if any(type(item) is not str for item in policy['arguments']):
            raise TypeError('argument_name_invalid')
        if any(not item.strip() for item in policy['arguments']) or len(set(policy['arguments'])) != len(policy['arguments']):
            raise ValueError('arguments_invalid')
    policy = registry.get(tool)
    return None if policy is None else {'mode':policy['mode'],'permission':policy['permission'],'arguments':policy['arguments']}

def exact_arguments(required_names, arguments):
    if type(required_names) is not tuple or type(arguments) is not dict:
        raise TypeError('arguments_input_invalid')
    if any(type(name) is not str for name in required_names) or any(type(key) is not str for key in arguments):
        raise TypeError('argument_name_invalid')
    if any(not name.strip() for name in required_names) or any(not key.strip() for key in arguments):
        raise ValueError('argument_name_blank')
    if len(set(required_names)) != len(required_names):
        raise ValueError('required_duplicate')
    for value in arguments.values():
        if type(value) not in {str, bool}:
            raise TypeError('argument_value_invalid')
        if type(value) is str and not value.strip():
            raise ValueError('argument_value_blank')
    return set(required_names) == set(arguments)

def scoped_lookup(trusted_tenant, resource_id, records):
    if type(trusted_tenant) is not str or type(resource_id) is not str or type(records) is not tuple:
        raise TypeError('lookup_input_invalid')
    if not trusted_tenant.strip() or not resource_id.strip():
        raise ValueError('lookup_id_blank')
    seen = set()
    for row in records:
        if type(row) is not dict:
            raise TypeError('record_invalid')
        if set(row) != {'tenant_id','resource_id','value'}:
            raise ValueError('record_shape_invalid')
        if any(type(row[key]) is not str for key in row):
            raise TypeError('record_value_invalid')
        if any(not row[key].strip() for key in row):
            raise ValueError('record_value_blank')
        key = (row['tenant_id'],row['resource_id'])
        if key in seen:
            raise ValueError('record_duplicate')
        seen.add(key)
    for row in records:
        if row['tenant_id'] == trusted_tenant and row['resource_id'] == resource_id:
            return row['value']
    return None

def approval_matches(grant, context):
    fields = {'tenant_id','principal_id','run_id','case_id','request_id','tool','argument_sha256'}
    if type(grant) is not dict or type(context) is not dict:
        raise TypeError('approval_input_invalid')
    if set(context) != fields or set(grant) != fields | {'approval_id','consumed'}:
        raise ValueError('approval_shape_invalid')
    for name in fields | {'approval_id'}:
        if type(grant[name]) is not str:
            raise TypeError('grant_value_invalid')
        if not grant[name].strip():
            raise ValueError('grant_value_blank')
    if any(type(context[name]) is not str for name in fields):
        raise TypeError('context_value_invalid')
    if any(not context[name].strip() for name in fields):
        raise ValueError('context_value_blank')
    digest = grant['argument_sha256']
    if len(digest) != 64 or any(char not in '0123456789abcdef' for char in digest):
        raise ValueError('grant_digest_invalid')
    context_digest = context['argument_sha256']
    if len(context_digest) != 64 or any(char not in '0123456789abcdef' for char in context_digest):
        raise ValueError('context_digest_invalid')
    if type(grant['consumed']) is not bool:
        raise TypeError('consumed_invalid')
    return not grant['consumed'] and all(grant[name] == context[name] for name in fields)

