def controlled_result(status, code):
    if type(status) is not str or type(code) is not str:
        raise TypeError('result_input_invalid')
    if not status.strip() or not code.strip():
        raise ValueError('result_blank')
    allowed = {
        'completed': {'ok'},
        'blocked': {'unknown_tool','argument_invalid','secret_material_rejected','permission_denied','approval_required','approval_not_found','approval_mismatch','approval_reused','step_limit_exceeded'},
        'failed': {'tool_failure','undo_not_found','undo_already_used','undo_conflict'},
    }
    if status not in allowed or code not in allowed[status]:
        raise ValueError('result_pair_invalid')
    return {'status':status,'code':code}

def contains_secret_key(payload, allowed_keys=()):
    if type(allowed_keys) is not tuple:
        raise TypeError('allowed_keys_invalid')
    if any(type(item) is not str for item in allowed_keys):
        raise TypeError('allowed_key_invalid')
    normalized_allowed = tuple(item.lower().replace('-','_') for item in allowed_keys)
    if any(not item.strip() for item in normalized_allowed) or len(set(normalized_allowed)) != len(normalized_allowed):
        raise ValueError('allowed_keys_malformed')
    secret_parts = ('api_key','authorization','credential','password','secret','token')
    def visit(value):
        if type(value) is dict:
            for key, nested in value.items():
                if type(key) is not str:
                    raise TypeError('payload_key_invalid')
                normalized = key.lower().replace('-','_')
                if any(part in normalized for part in secret_parts) and normalized not in normalized_allowed:
                    return True
                if visit(nested):
                    return True
            return False
        if type(value) in {list, tuple}:
            return any(visit(item) for item in value)
        if value is None or type(value) in {str, bool, int}:
            return False
        raise TypeError('payload_value_invalid')
    return visit(payload)

import hashlib
import json

def safe_audit_projection(event):
    required = {'sequence','tenant_id','principal_id','tool','code','arguments','exception'}
    if type(event) is not dict:
        raise TypeError('event_invalid')
    if set(event) != required:
        raise ValueError('event_shape_invalid')
    if type(event['sequence']) is not int:
        raise TypeError('sequence_invalid')
    if event['sequence'] < 1:
        raise ValueError('sequence_range_invalid')
    for name in ('tenant_id','principal_id','tool','code'):
        if type(event[name]) is not str:
            raise TypeError('metadata_invalid')
        if not event[name].strip():
            raise ValueError('metadata_blank')
    if type(event['arguments']) is not dict:
        raise TypeError('arguments_invalid')
    for key, value in event['arguments'].items():
        if type(key) is not str or type(value) not in {str, bool}:
            raise TypeError('argument_entry_invalid')
    if event['exception'] is not None and type(event['exception']) is not str:
        raise TypeError('exception_invalid')
    raw = json.dumps(event['arguments'],sort_keys=True,separators=(',',':')).encode()
    return {'sequence':event['sequence'],'tenant_id':event['tenant_id'],'principal_id':event['principal_id'],'tool':event['tool'],'code':event['code'],'argument_sha256':hashlib.sha256(raw).hexdigest()}

