def canonical_argument_digest(arguments):
    if type(arguments) is not dict:
        raise TypeError('arguments_invalid')
    for key, value in arguments.items():
        if type(key) is not str or type(value) not in {str, bool}:
            raise TypeError('argument_entry_invalid')
        if not key.strip() or (type(value) is str and not value.strip()):
            raise ValueError('argument_entry_blank')
