import hashlib
import json

def linked_event(previous_hash, sequence, body):
    if type(sequence) is not int or type(body) is not dict:
        raise TypeError('event_input_invalid')
    if sequence < 1:
        raise ValueError('sequence_invalid')
    if previous_hash is not None and type(previous_hash) is not str:
        raise TypeError('previous_hash_invalid')
    if (sequence == 1) != (previous_hash is None):
        raise ValueError('predecessor_presence_invalid')
    if previous_hash is not None and (len(previous_hash) != 64 or any(c not in '0123456789abcdef' for c in previous_hash)):
        raise ValueError('previous_hash_format_invalid')
    if set(body) != {'event_type','tenant_id','tool','code','argument_sha256'}:
        raise ValueError('event_body_shape_invalid')
    if any(type(value) is not str for value in body.values()):
        raise TypeError('event_body_value_invalid')
    if any(not value.strip() for value in body.values()):
        raise ValueError('event_body_blank')
    digest = body['argument_sha256']
    if len(digest) != 64 or any(c not in '0123456789abcdef' for c in digest):
        raise ValueError('argument_digest_invalid')
    copied = dict(body)
    raw = json.dumps({'sequence':sequence,'previous_hash':previous_hash,'body':copied},sort_keys=True,separators=(',',':')).encode()
    return {'sequence':sequence,'previous_hash':previous_hash,'body':copied,'event_hash':hashlib.sha256(raw).hexdigest()}

