import hashlib
import json

def verify_audit_chain(events):
    if type(events) is not tuple:
        raise TypeError('events_invalid')
    if not events:
        raise ValueError('events_empty')
    previous = None
    for expected_sequence, event in enumerate(events,1):
        if type(event) is not dict:
            raise TypeError('event_invalid')
        if set(event) != {'sequence','previous_hash','body','event_hash'}:
            raise ValueError('event_shape_invalid')
        if type(event['sequence']) is not int or type(event['body']) is not dict or type(event['event_hash']) is not str:
            raise TypeError('event_value_invalid')
        if event['sequence'] != expected_sequence:
            raise ValueError('event_sequence_invalid')
        if event['previous_hash'] is not None and type(event['previous_hash']) is not str:
            raise TypeError('predecessor_invalid')
        if set(event['body']) != {'event_type','tenant_id','tool','code','argument_sha256'}:
            raise ValueError('event_body_shape_invalid')
        if any(type(value) is not str for value in event['body'].values()):
            raise TypeError('event_body_value_invalid')
        if any(not value.strip() for value in event['body'].values()):
            raise ValueError('event_body_blank')
        hashes = [event['event_hash'],event['body']['argument_sha256']]
        if any(len(value) != 64 or any(c not in '0123456789abcdef' for c in value) for value in hashes):
            raise ValueError('hash_format_invalid')
        raw = json.dumps({'sequence':event['sequence'],'previous_hash':event['previous_hash'],'body':event['body']},sort_keys=True,separators=(',',':')).encode()
        expected_hash = hashlib.sha256(raw).hexdigest()
        if event['previous_hash'] != previous or event['event_hash'] != expected_hash:
            return False
        previous = event['event_hash']
    return True

