def reversal_decision(receipt, trusted_tenant, current_value, used_tokens):
    if type(receipt) is not dict or type(trusted_tenant) is not str or type(current_value) is not str or type(used_tokens) is not tuple:
        raise TypeError('reversal_input_invalid')
    if set(receipt) != {'tenant_id','undo_token','before','after'}:
        raise ValueError('receipt_shape_invalid')
    if any(type(value) is not str for value in receipt.values()) or any(type(value) is not str for value in used_tokens):
        raise TypeError('reversal_value_invalid')
    if any(not value.strip() for value in receipt.values()) or not trusted_tenant.strip() or any(not value.strip() for value in used_tokens):
        raise ValueError('reversal_value_blank')
    if receipt['before'] not in {'clear','needs_human'} or receipt['after'] not in {'clear','needs_human'} or current_value not in {'clear','needs_human'}:
        raise ValueError('flag_value_invalid')
    if len(set(used_tokens)) != len(used_tokens):
        raise ValueError('used_token_duplicate')
    if receipt['tenant_id'] != trusted_tenant:
        return 'undo_not_found'
    if receipt['undo_token'] in used_tokens:
        return 'undo_already_used'
    if current_value != receipt['after']:
        return 'undo_conflict'
    return 'ok'

import hashlib

def set_review_flag(flags, trusted_tenant, flag_id, value):
    if type(flags) is not dict or type(trusted_tenant) is not str or type(flag_id) is not str or type(value) is not str:
        raise TypeError('flag_input_invalid')
    if not trusted_tenant.strip() or not flag_id.strip():
        raise ValueError('flag_id_blank')
    if value not in {'clear','needs_human'}:
        raise ValueError('flag_value_invalid')
    for key, existing in flags.items():
        if type(key) is not tuple or len(key) != 2 or any(type(part) is not str for part in key) or type(existing) is not str:
            raise TypeError('flag_store_invalid')
        if any(not part.strip() for part in key) or existing not in {'clear','needs_human'}:
            raise ValueError('flag_store_value_invalid')
    key = (trusted_tenant,flag_id)
    before = flags.get(key,'clear')
    flags[key] = value
    raw = '|'.join((trusted_tenant,flag_id,before,value)).encode()
    token = 'undo-' + hashlib.sha256(raw).hexdigest()[:24]
    return {'tenant_id':trusted_tenant,'flag_id':flag_id,'before':before,'after':value,'undo_token':token}

