def revert_review_flag(flags, receipt, trusted_tenant, used_tokens):
    if type(flags) is not dict or type(receipt) is not dict or type(trusted_tenant) is not str or type(used_tokens) is not set:
        raise TypeError('revert_input_invalid')
    if set(receipt) != {'tenant_id','flag_id','before','after','undo_token'}:
        raise ValueError('receipt_shape_invalid')
    if any(type(value) is not str for value in receipt.values()) or any(type(value) is not str for value in used_tokens):
        raise TypeError('revert_value_invalid')
    if any(not value.strip() for value in receipt.values()) or not trusted_tenant.strip() or any(not value.strip() for value in used_tokens):
        raise ValueError('revert_value_blank')
    if receipt['before'] not in {'clear','needs_human'} or receipt['after'] not in {'clear','needs_human'}:
        raise ValueError('receipt_flag_invalid')
    for key, value in flags.items():
        if type(key) is not tuple or len(key) != 2 or any(type(part) is not str for part in key) or value not in {'clear','needs_human'}:
            raise TypeError('flag_store_invalid')
    if receipt['tenant_id'] != trusted_tenant:
        raise ValueError('undo_not_found')
    token = receipt['undo_token']
    if token in used_tokens:
        raise ValueError('undo_already_used')
    key = (trusted_tenant,receipt['flag_id'])
    if flags.get(key,'clear') != receipt['after']:
        raise ValueError('undo_conflict')
    flags[key] = receipt['before']
    used_tokens.add(token)
    return receipt['before']

