def policy_decision(policy, granted, approval_present):
    if type(policy) is not dict or type(granted) is not tuple or type(approval_present) is not bool:
        raise TypeError('policy_input_invalid')
    if set(policy) != {'mode','permission'}:
        raise ValueError('policy_shape_invalid')
    if type(policy['mode']) is not str or type(policy['permission']) is not str or any(type(item) is not str for item in granted):
        raise TypeError('policy_value_invalid')
    if policy['mode'] not in {'read','write'} or not policy['permission'].strip() or any(not item.strip() for item in granted):
        raise ValueError('policy_value_invalid')
    if len(set(granted)) != len(granted):
        raise ValueError('granted_duplicate')
    if policy['permission'] not in granted:
        return 'permission_denied'
    if policy['mode'] == 'write' and not approval_present:
        return 'approval_required'
    return 'ok'

def requires_approval(mode):
    if type(mode) is not str:
        raise TypeError('mode_invalid')
    if not mode.strip() or mode not in {'read','write'}:
        raise ValueError('mode_invalid')
    return mode == 'write'

def public_failure(error_name):
    if type(error_name) is not str:
        raise TypeError('error_name_invalid')
    if not error_name.strip():
        raise ValueError('error_name_blank')
    known = {
        'permission_error': {'status':'blocked','code':'permission_denied'},
        'approval_error': {'status':'blocked','code':'approval_required'},
        'step_error': {'status':'blocked','code':'step_limit_exceeded'},
        'undo_conflict': {'status':'failed','code':'undo_conflict'},
    }
    return dict(known.get(error_name,{'status':'failed','code':'tool_failure'}))

def valid_lifecycle(events):
    if type(events) is not tuple:
        raise TypeError('events_invalid')
    if any(type(event) is not str for event in events):
        raise TypeError('event_invalid')
    if any(not event.strip() for event in events):
        raise ValueError('event_blank')
    allowed = {
        ('requested','executed'),
        ('requested','failed'),
        ('requested','denied'),
        ('requested','step_limit'),
        ('requested','approval_checked','executed'),
        ('requested','approval_checked','reversed'),
        ('requested','approval_checked','failed'),
    }
    return events in allowed
